#!/bin/sh
# ============================================================
#  OpenMinis-pojia installer v1.1
#  iOS + Android (same data layout, same script)
#  SOUL.md + GLOBAL.md + 13 skills, base64 payload, ascii-only
#
#  remote:
#    curl -fsSL https://raw.githubusercontent.com/gxxHuang/OpenMinis-pojia/main/armor-install.sh | sh
#    curl -fsSL https://raw.githubusercontent.com/gxxHuang/OpenMinis-pojia/main/armor-install.sh | sh -s status
#    curl -fsSL https://raw.githubusercontent.com/gxxHuang/OpenMinis-pojia/main/armor-install.sh | sh -s verify
#    curl -fsSL https://raw.githubusercontent.com/gxxHuang/OpenMinis-pojia/main/armor-install.sh | sh -s revert
#
#  local:
#    sh armor-install.sh [install|status|verify|revert]
# ============================================================

set -u
M=/var/minis
SOUL="$M/memory/SOUL.md"
GLOBAL="$M/memory/GLOBAL.md"
SK="$M/skills"
ROOT=/OpenMinis-pojia
OUT=$ROOT/out
TS=$(date +%Y%m%d-%H%M%S)
REPO="gxxHuang/OpenMinis-pojia"

ok(){   printf '[ok]   %s\n' "$1"; }
warn(){ printf '[warn] %s\n' "$1"; }
fail(){ printf '[FAIL] %s\n' "$1"; }
lines(){ wc -l < "$1" 2>/dev/null | tr -d ' '; }

