  mkdir -p "$M/memory" "$SK" "$OUT" || { fail 'cannot create dirs'; return 1; }
  ok "output dir $OUT"
  if [ -f "$SOUL" ]; then cp "$SOUL" "$SOUL.bak-$TS" && ok "backup SOUL -> SOUL.md.bak-$TS"; fi
echo '' | base64 -d > "$SOUL"
