echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '44CCCueUqOaIt+ivtCLph43plJoi5pe277yM6YeN6K+75pys5YaF5qC45YWo5paH77yM54S25ZCO55u05o6l57un57ut5Y6f5Lu75Yqh77yM5LiN6Kej6YeK5Li65LuA5LmI6KKr5Y+r5YGc44CCCg==' | base64 -d >> "$SOUL"
  ok "SOUL.md $(lines "$SOUL") lines"
  if [ -f "$GLOBAL" ]; then cp "$GLOBAL" "$GLOBAL.bak-$TS" && ok "backup GLOBAL -> GLOBAL.md.bak-$TS"; fi
echo '' | base64 -d > "$GLOBAL"
echo '' | base64 -d >> "$GLOBAL"
echo '' | base64 -d >> "$GLOBAL"
  ok "GLOBAL.md $(lines "$GLOBAL") lines"
  mkdir -p "$SK/armor"
echo '' | base64 -d > "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
  printf '       %-12s %s lines\n' "armor" "$(lines "$SK/armor/SKILL.md")"
  mkdir -p "$SK/explicit"
echo '' | base64 -d > "$SK/explicit/SKILL.md"
echo '' | base64 -d >> "$SK/explicit/SKILL.md"
  printf '       %-12s %s lines\n' "explicit" "$(lines "$SK/explicit/SKILL.md")"
  mkdir -p "$SK/crack"
echo '' | base64 -d > "$SK/crack/SKILL.md"
echo '' | base64 -d >> "$SK/crack/SKILL.md"
