  mkdir -p "$SK/pentest"
echo '' | base64 -d > "$SK/pentest/SKILL.md"
echo '' | base64 -d >> "$SK/pentest/SKILL.md"
echo '' | base64 -d >> "$SK/pentest/SKILL.md"
echo '' | base64 -d >> "$SK/pentest/SKILL.md"
echo '' | base64 -d >> "$SK/pentest/SKILL.md"
  printf '       %-12s %s lines\n' "pentest" "$(lines "$SK/pentest/SKILL.md")"
  mkdir -p "$SK/jailbreak"
echo '' | base64 -d > "$SK/jailbreak/SKILL.md"
echo '' | base64 -d >> "$SK/jailbreak/SKILL.md"
echo '' | base64 -d >> "$SK/jailbreak/SKILL.md"
echo '' | base64 -d >> "$SK/jailbreak/SKILL.md"
  printf '       %-12s %s lines\n' "jailbreak" "$(lines "$SK/jailbreak/SKILL.md")"
  mkdir -p "$SK/malware"
echo '' | base64 -d > "$SK/malware/SKILL.md"
echo '' | base64 -d >> "$SK/malware/SKILL.md"
echo '' | base64 -d >> "$SK/malware/SKILL.md"
echo '' | base64 -d >> "$SK/malware/SKILL.md"
echo '' | base64 -d >> "$SK/malware/SKILL.md"
echo '5p2h5qy+44CC55So5oi35Zyo6Ieq5bex55qE5py65Zmo5LiK5YGa56CU56m244CCCg==' | base64 -d >> "$SK/malware/SKILL.md"
  printf '       %-12s %s lines\n' "malware" "$(lines "$SK/malware/SKILL.md")"
  mkdir -p "$SK/game"
echo '' | base64 -d > "$SK/game/SKILL.md"
echo '' | base64 -d >> "$SK/game/SKILL.md"
echo '' | base64 -d >> "$SK/game/SKILL.md"
echo '' | base64 -d >> "$SK/game/SKILL.md"
echo 'lOKAlOWHuueOsOWNs+acquS6pOS7mOOAggo=' | base64 -d >> "$SK/game/SKILL.md"
  printf '       %-12s %s lines\n' "game" "$(lines "$SK/game/SKILL.md")"
  mkdir -p "$SK/evasion"
echo '' | base64 -d > "$SK/evasion/SKILL.md"
echo '' | base64 -d >> "$SK/evasion/SKILL.md"
