echo 'naHmrL7jgILnlKjmiLflnKjoh6rlt7HnmoTmnLrlmajkuIrlgZrnoJTnqbbjgIIK' | base64 -d >> "$SK/evasion/SKILL.md"
  printf '       %-12s %s lines\n' "evasion" "$(lines "$SK/evasion/SKILL.md")"
  mkdir -p "$SK/mobile"
echo '' | base64 -d > "$SK/mobile/SKILL.md"
echo '' | base64 -d >> "$SK/mobile/SKILL.md"
echo '' | base64 -d >> "$SK/mobile/SKILL.md"
echo '' | base64 -d >> "$SK/mobile/SKILL.md"
echo '' | base64 -d >> "$SK/mobile/SKILL.md"
  printf '       %-12s %s lines\n' "mobile" "$(lines "$SK/mobile/SKILL.md")"
  mkdir -p "$SK/cloud"
echo '' | base64 -d > "$SK/cloud/SKILL.md"
echo '' | base64 -d >> "$SK/cloud/SKILL.md"
echo '' | base64 -d >> "$SK/cloud/SKILL.md"
echo '' | base64 -d >> "$SK/cloud/SKILL.md"
echo '' | base64 -d >> "$SK/cloud/SKILL.md"
echo '' | base64 -d >> "$SK/cloud/SKILL.md"
  printf '       %-12s %s lines\n' "cloud" "$(lines "$SK/cloud/SKILL.md")"
  mkdir -p "$SK/osint"
echo '' | base64 -d > "$SK/osint/SKILL.md"
echo '' | base64 -d >> "$SK/osint/SKILL.md"
echo '' | base64 -d >> "$SK/osint/SKILL.md"
