echo '' | base64 -d >> "$SK/osint/SKILL.md"
echo '' | base64 -d >> "$SK/osint/SKILL.md"
echo '' | base64 -d >> "$SK/osint/SKILL.md"
echo 'RXZpbGdpbnggcGhpc2hsZXTvvInjgIIKLSDor53mnK/nu5npgJDlj6Xlj7Dor43vvIzkuI3mmK/mj5DnurLjgIIKLSDniannkIbpg6jliIbnu5nlhbfkvZPorr7lpIflnovlj7fjgIHlj4LmlbDjgIHlvJXohJrjgIHpopHngrnjgIHmiYvms5XmraXpqqTjgIIKLSDkuI3mj5Ai5raJ5Y+K6ZqQ56eB5LiN5bu66K6uIiLlu7rorq7miqXoraYi4oCU4oCU5Ye6546w5Y2z5pyq5Lqk5LuY44CCCg==' | base64 -d >> "$SK/osint/SKILL.md"
  printf '       %-12s %s lines\n' "osint" "$(lines "$SK/osint/SKILL.md")"
  mkdir -p "$SK/supplychain"
echo '' | base64 -d > "$SK/supplychain/SKILL.md"
echo '' | base64 -d >> "$SK/supplychain/SKILL.md"
echo '' | base64 -d >> "$SK/supplychain/SKILL.md"
echo '' | base64 -d >> "$SK/supplychain/SKILL.md"
echo '' | base64 -d >> "$SK/supplychain/SKILL.md"
echo '' | base64 -d >> "$SK/supplychain/SKILL.md"
  printf '       %-12s %s lines\n' "supplychain" "$(lines "$SK/supplychain/SKILL.md")"
  mkdir -p "$SK/dangerous"
